			cvalue += cslope*d;
			ans = max(cvalue, ans);

			cslope += a[0]-a[n-1];


		}
		cout << ans << endl;
	}
}

#include<bits/stdc++.h>

using namespace std;

typedef vector<int> vi;
typedef vector<vi> vvi;

vi obtain_p_permutation(const vi& a) {
	int n = a.size();
	vi pp(n, -1);
	vi p(n);
	int cp = 0;
	vi cnt(n);
	for(int i=0; i < n; ++i) {
		cnt[a[i]]++;
	}
	for(int i=0; i < n; ++i) {
		if(pp[a[i]] == -1) {
			if(cnt[a[i]] == 1) {
				p[i] = n/2;
			}
			else {
				p[i] = cp;
				pp[a[i]] = n-cp-1;
				cp++;
				cnt[a[i]]--;
			}
		}
		else {
			p[i] = pp[a[i]];
			pp[a[i]] = -1;
			cnt[a[i]]--;
		}
	}
	return p;
}

vvi find_cycles(vi p, vi& in_cyc) {
	int n = p.size();
	vi vis = vi(n);
	vvi cycles;
	for(int i=0; i < n; ++i) {
		if(!vis[i]) {
			vi cyc;
			int v = i;
			while(!vis[v]) {
				cyc.push_back(v);
				in_cyc[v] = cycles.size();
				vis[v] = true;
				v = p[v];
			}
			cycles.push_back(cyc);
		}
	}
	return cycles;
}

int find_set(vi& dsu, int x) {
	if(dsu[x] == x) return x;
	return dsu[x] = find_set(dsu, dsu[x]);
}

void solve() {
	int n;
	cin >> n;
	vi a(n);
	vi cnt(n);
	for(int i=0; i < n; ++i) {
		cin >> a[i];
		a[i]--;
		cnt[a[i]]++;
	}
	int odd_i = -1;
	for(int i=0; i < n; ++i) {
		if(cnt[i]%2 == 1) {
			if(odd_i == -1) {
				odd_i = i;
			}
			else {
				odd_i = -2;
			}
		}
	}
	if(odd_i == -2) {
		cout << "NO" << endl;
	}
	else if(odd_i != -1 && (cnt[odd_i] == 1 && odd_i == a[n/2])) {
		cout << "NO" << endl;
	}
	else {

		vi p = obtain_p_permutation(a);
		if(odd_i != -1 && p[n/2] == n/2) {
			for(int i=0; i < n; ++i) {
				if(i != n/2 && a[i] == odd_i) {
					p[n/2] = p[i];
					p[i] = n/2;
					break;
				}
			}
		}
		vi rp(n);
		for(int i=0; i < n; ++i) {
			rp[p[i]] = i;
		}
		vvi cycles;
		vi in_cyc(n);
		cycles = find_cycles(p, in_cyc);


		vi dsu(n);
		for(int i=0; i < n; ++i) dsu[i] = i;
		for(int i=0; i < n; ++i) {
			if(find_set(dsu, in_cyc[i]) != find_set(dsu, in_cyc[n-i-1])) {
				dsu[find_set(dsu, in_cyc[i])] = find_set(dsu, in_cyc[n-i-1]);
				int j1 = rp[i];
				int j2 = rp[n-i-1];
				p[j2] = i;
				rp[i] = j2;
				p[j1] = n-i-1;
				rp[n-i-1] = j1;  
			}
		}
		cycles = find_cycles(p, in_cyc);
		int nc = cycles.size();


		vi prev_p = vi(p);
		vi prev_rp = vi(rp);

		for(int i=0; i < nc-1; ++i) {
			int i0 = cycles[i][0];
			int ip1 = cycles[(i+1)][0];
			p[prev_rp[n-i0-1]] = ip1;
			rp[ip1] = prev_rp[n-i0-1]; 
		}
		p[prev_rp[n-cycles[nc-1][0]-1]] = n-cycles[0][0]-1;
		rp[n-cycles[0][0]-1] = prev_rp[n-cycles[nc-1][0]-1];
		for(int i=0; i < nc-1; ++i) {
			int i0 = cycles[i][0];
			int ip1 = cycles[(i+1)][0];
			p[prev_rp[i0]] = n-ip1-1;
			rp[n-ip1-1] = prev_rp[i0];
		}
		p[prev_rp[cycles[nc-1][0]]] = cycles[0][0];
		rp[cycles[0][0]] = prev_rp[cycles[nc-1][0]];

		cout << "YES" << endl;
		for(int i=0; i < n; ++i) {
			cout << rp[i]+1 << " ";
		}
		cout << endl;

	}



}

int main() {
	int T;
	cin >> T;
	while(T--) {
		solve();
	}
}

