using namespace std;

typedef __int128 ll; 
typedef vector<ll> vi;
typedef vector<vi> vvi;


ll read_ll() {
	string s;
	cin >> s;
	ll x = 0;
	for(int i=0; i < (int)s.length(); ++i) {
		x *= 10;
		x += ll(s[i]-'0');
	}
	return x;
}

void print_ll(ll x) {
	vector<int> p;
	while(x > 0) {
		p.push_back((int)(x%10));
		x /= 10;
	}
	reverse(p.begin(), p.end());
	for(int y : p) cout << y;
}

inline ll ctz(ll x) {
	long long a = x&((ll(1)<<ll(63))-ll(1));
	long long b = x>>ll(63);
	if(a == 0) return ll(63)+__builtin_ctzll(b);
	return __builtin_ctzll(a);  
}

inline ll abll(ll x) {
	return x >= 0 ? x : -x;
}

ll gcd(ll a, ll b) {
	if(b == 0) return a;
	if(a == 0) return b;

	int az = ctz(a);
	int bz = ctz(b);
	int shift = min(az, bz);
	b >>= bz;

	while(a != 0) {
		a >>= az;
		ll diff = b-a;
		if(diff) az = ctz(diff);
		b = min(a, b);
		a = abll(diff);
	}
	return b << shift;
}

void init_st(vi& st, const vi& v) {
	int n = v.size();
	for(int i=0; i < n; ++i) {
		st[n+i] = v[i];
	}
	for(int i=n-1; i >= 1; --i) {
		st[i] = gcd(st[2*i], st[2*i+1]);
	}
}

void update_st(vi& st, int i, ll x) {
	int n = (int)st.size() / 2;
	int pos = n+i;
	st[pos] = x;
	while(pos > 1) {
		pos /= 2;
		st[pos] = gcd(st[2*pos], st[2*pos+1]);
	}
}

void solve(const vi& a, const vi& b, vector<bool>& ai, vector<bool>& bi) {
	int n = a.size();
	int m = b.size();
	vvi st_a = vvi(n, vi(2*m, 0));
	vvi st_b = vvi(m, vi(2*n, 0));
	for(int i=0; i < n; ++i) {
		vi af(m);
		for(int j=0; j < m; ++j) {
			af[j] = a[i]/gcd(a[i], b[j]);
		}
		init_st(st_a[i], af);
	}
	for(int i=0; i < m; ++i) {
		vi bf(n);
		for(int j=0; j < n; ++j) {
			bf[j] = b[i]/gcd(b[i], a[j]);
		}
		init_st(st_b[i], bf);
	}
	queue<int> dq;
	for(int i=0; i < n; ++i) {
		if(st_a[i][1] > 1) {
		       	dq.push(i);
			ai[i] = false;
		}
	}
	for(int i=0; i < m; ++i) {
		if(st_b[i][1] > 1) {
		       	dq.push(n+i);
			bi[i] = false;
		}
	}
	while(!dq.empty()) {
		int idx = dq.front();
		dq.pop();
		if(idx < n) {
			int i = idx;
			for(int j=0; j < m; ++j) {
				if(bi[j]) {
					update_st(st_b[j], i, b[j]);
					if(st_b[j][1] > 1) {
						dq.push(n+j);
						bi[j] = false;
					}
				}
			}
		}
		else {
			int i = idx-n;
			for(int j=0; j < n; ++j) {
				if(ai[j]) {
					update_st(st_a[j], i, a[j]);
					if(st_a[j][1] > 1) { 
						dq.push(j);
						ai[j] = false;
					}
				}
			}
		}
	}	

}



